const $=s=>document.querySelector(s);
const escapeHtml=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const catalog=[{"id": "soon", "name": "SOON", "symbol": "SOON", "mark": "S", "bg": "#e2e9fa", "color": "#586bb6", "account": "@soon_svm"}, {"id": "near", "name": "NEAR Protocol", "symbol": "NEAR", "mark": "N", "bg": "#e0efe8", "color": "#3a7257", "account": "@NEARProtocol"}, {"id": "pha", "name": "Phala", "symbol": "PHA", "mark": "P", "bg": "#eef0df", "color": "#6d7942", "account": "@PhalaNetwork"}, {"id": "nil", "name": "Nillion", "symbol": "NIL", "mark": "N", "bg": "#e7e5fa", "color": "#7665ad", "account": "@nillion"}];
const events=[];
const defaultRules=[];
let savedState={};try{savedState=JSON.parse(localStorage.getItem('signal-live-v1')||'{}')}catch{}
let state={hiddenProjects:savedState.hiddenProjects||[],pinnedProjects:savedState.pinnedProjects||[],projectGroups:savedState.projectGroups||{},projectOrder:savedState.projectOrder||savedState.projects||[],unreadProjectsOnly:savedState.unreadProjectsOnly||false,projects:(savedState.projects||['soon','near','pha','nil']).filter(id=>catalog.some(p=>p.id===id)),saved:savedState.saved||[],read:savedState.read||[],rules:Array.isArray(savedState.rules)?savedState.rules:defaultRules,view:'feed',project:null,filter:'all',query:'',important:false};
function persist(){try{localStorage.setItem('signal-live-v1',JSON.stringify({hiddenProjects:state.hiddenProjects,pinnedProjects:state.pinnedProjects,projectGroups:state.projectGroups,projectOrder:state.projectOrder,unreadProjectsOnly:state.unreadProjectsOnly,projects:state.projects,saved:state.saved,read:state.read,rules:state.rules}))}catch{toast('浏览器无法保存偏好，本次会话仍可使用')}}
const token=p=>`<span class="token" style="--token-bg:${p.bg};--token-color:${p.color}"><span>${escapeHtml(p.mark)}</span>${p.logo&&/^https:\/\/pbs\.twimg\.com\//.test(p.logo)?`<img class="project-logo" src="${escapeHtml(p.logo)}" alt="" loading="lazy" referrerpolicy="no-referrer">`:''}</span>`;
document.addEventListener('error',e=>{if(e.target.matches?.('.project-logo'))e.target.remove()},true);
let projectListQuery='';
function renderProjectList(){
 const followed=state.projects.map(id=>catalog.find(p=>p.id===id)).filter(Boolean);
 const list=followed.filter(p=>(p.name+' '+p.symbol+' '+(p.account||'')).toLowerCase().includes(projectListQuery.trim().toLowerCase()));
 $('#projects').innerHTML=list.map(p=>{const unread=events.filter(e=>e.p===p.id&&!state.read.includes(e.id)).length;return `<button class="project-button ${state.project===p.id?'selected':''}" data-project="${escapeHtml(p.id)}" aria-current="${state.project===p.id?'page':'false'}" title="${escapeHtml(p.name)} · ${unread} 条未读">${token(p)}<span class="project-label"><strong>${escapeHtml(p.name)}</strong><span>${escapeHtml(p.symbol)}</span></span>${unread?`<small class="unread-badge" aria-label="${unread} 条未读">${unread>99?'99+':unread}</small>`:''}</button>`}).join('')||'<p class="project-list-empty">没有匹配的关注项目</p>';
 $('#project-count').textContent=followed.length;
}

function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3000)}
function filteredEvents(){return events.filter(e=>(e.projectIds||[e.p]).some(p=>state.projects.includes(p))&&(!state.project||(e.projectIds||[e.p]).includes(state.project))&&(state.view!=='saved'||state.saved.includes(e.id)||(e.memberIds||[]).some(id=>state.saved.includes(parseInt(id.slice(5,17),16))))&&(state.filter==='all'||(e.providerKind?(e.providerKind==='listing'?'news':'market'):e.type)===state.filter)&&(!state.important||e.high)&&(!state.query||[e.title,e.summary,catalog.find(p=>p.id===e.p).name,catalog.find(p=>p.id===e.p).symbol].join(' ').toLowerCase().includes(state.query.toLowerCase())))}
function render(){
 renderProjectList();
 $('#unread-count').textContent=events.filter(e=>state.projects.includes(e.p)&&e.type==='news'&&e.publishedAt>=Date.now()-7*86400000&&!state.read.includes(e.id)).length;$('#saved-count').textContent=state.saved.length;
 document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===state.view&&!state.project));
 const p=catalog.find(x=>x.id===state.project);$('#crumb').textContent=p?p.name:({feed:'情报收件箱',saved:'稍后阅读',rules:'提醒规则'}[state.view]);
 $('#page-title').textContent=p?p.name:({feed:'值得关注的，都在这里。',saved:'留给稍后的好信息。',rules:'只提醒你在意的变化。'}[state.view]);$('#page-subtitle').textContent=p?'项目消息、市场信号与事件进展。':({feed:'把分散的消息，连成清晰的项目脉络。',saved:'收藏的事件集中在这里，随时回来继续阅读。',rules:'配置可保存于本设备；自定义规则仅保存配置；固定行情指标由后台计算。'}[state.view]);
 $('#project-overview').innerHTML=p?`<section class="project-overview">${token(p)}<div><h2>${p.symbol} <span class="tag">测试项目</span></h2><p>${p.account||'去中心化项目，无统一官方账号'} · 来源覆盖详见状态</p></div><button class="secondary" data-action="sources">查看来源</button><button class="primary" data-action="rule">＋ 设置提醒</button></section>`:'';
 $('#feed-controls').hidden=state.view==='rules';document.querySelectorAll('[data-filter]').forEach(b=>{const active=b.dataset.filter===state.filter;b.classList.toggle('active',active);b.setAttribute('aria-selected',active)});
 if(state.view==='rules'){renderRules()}else{const list=filteredEvents();$('#result-count').textContent=`真实数据 · ${list.length} 条事件`;$('#feed').innerHTML=list.length?list.map(eventCard).join(''):`<div class="empty"><h3>${state.view==='saved'?'还没有收藏的事件':'没有符合条件的事件'}</h3><p>${state.view==='saved'?'点击事件右下角的收藏按钮，留待稍后阅读。':'尝试切换分类或清除筛选；当前没有符合条件的已采集内容。'}</p><button class="secondary" data-action="clear">清除筛选</button></div>`}
 $('#market-watch').innerHTML=state.projects.slice(0,4).map(id=>{const p=catalog.find(x=>x.id===id);return `<div class="watch-row">${token(p)}<div class="name">${p.symbol}<small>永续价格</small></div><svg viewBox="0 0 70 28" aria-hidden="true"><path d="${p.id==='sol'?'M0 6L7 10L13 7L20 15L27 12L34 19L41 13L48 21L55 19L62 23L70 20':'M0 22L7 17L14 19L21 12L28 16L35 9L42 13L49 6L56 9L63 3L70 5'}" fill="none" stroke="${p.id==='sol'?'#ba8079':'#7eaa8e'}" stroke-width="1.5"/></svg><div class="price">${p.price?'$'+p.price:'—'}<small class="${p.id==='sol'?'down':''}">${p.change||'未提供数据'}</small></div></div>`}).join('');$('.brief-stats strong').textContent=String(state.projects.length).padStart(2,'0');
}
function eventCard(e){const p=catalog.find(p=>p.id===e.p);return `<article class="event-card ${state.read.includes(e.id)?'read':''}"><div class="event-meta">${token(p)}<span class="project-name">${p.name}</span><span>· ${escapeHtml(e.topic)}</span>${e.high?'<span class="tag high">'+(e.type==='news'?'重点候选':'条件触发')+'</span>':''}<time>${escapeHtml(e.time)}</time></div><button class="event-title" data-event="${e.id}">${escapeHtml(e.title)}</button><p class="event-summary">${escapeHtml(e.summary)}</p>${e.metrics?`<div class="metric-strip">${e.metrics.map(m=>`<div><span>${escapeHtml(m[0])}</span><strong>${escapeHtml(m[1])}</strong></div>`).join('')}</div>`:''}<div class="event-bottom"><span class="tag">${escapeHtml(e.source)}</span><span>${escapeHtml(e.sources||'')}</span><button class="save ${state.saved.includes(e.id)?'saved':''}" data-save="${e.id}" aria-label="${state.saved.includes(e.id)?'取消收藏':'收藏事件'}" aria-pressed="${state.saved.includes(e.id)}">${state.saved.includes(e.id)?'▣':'▢'}</button></div></article>`}
function openDetail(id){const e=events.find(x=>x.id===id);if(!e)return;if(!state.read.includes(id))state.read.push(id);persist();render();const p=catalog.find(x=>x.id===e.p);$('#detail-content').innerHTML=`<div class="dialog-inner">${formTitle(p.name+' · '+e.topic)}<span class="tag">${escapeHtml(e.source)}</span><h1>${escapeHtml(e.title)}</h1><p>${escapeHtml(e.detail||e.summary)}</p>${e.metrics?`<div class="metric-strip">${e.metrics.map(m=>`<div><span>${escapeHtml(m[0])}</span><strong>${escapeHtml(m[1])}</strong></div>`).join('')}</div>`:''}<h3>来源与时间</h3><div class="evidence">${escapeHtml(e.uncertain||'来源表述未经独立核实。未进行自动团队身份推断或 KOL 归因。')}<br>原始时间：${escapeHtml(e.time)}<br>系统获取：${formatTime(e.discoveredAt)}<br>${e.url?`<a class="source-link" target="_blank" rel="noopener noreferrer" href="${escapeHtml(safeUrl(e.url))}">打开原始来源 ↗</a>`:''}</div><div class="modal-footer"><button class="secondary" data-save="${e.id}">${state.saved.includes(id)?'取消收藏':'稍后阅读'}</button><button class="primary" data-detail-rule="${e.p}">配置提醒</button></div></div>`;$('#detail-dialog').showModal()}
function showForm(html){$('#form-content').innerHTML=`<div class="dialog-inner">${html}</div>`;if(!$('#form-dialog').open)$('#form-dialog').showModal()}
function formTitle(title){return `<div class="dialog-top"><h2>${title}</h2><button class="icon-btn" data-close aria-label="关闭弹窗">×</button></div>`}
function openAdd(){showForm(`${formTitle('关注一个项目')}<p>搜索项目名称或官方账号。当前测试范围为 SOON、NEAR、PHA、NIL；暂不支持任意项目识别。</p><label class="field">项目名称 / 官方账号<input id="project-search" placeholder="例如 Ethereum、@aave" autocomplete="off"></label><div id="candidates"></div>`);renderCandidates('');$('#project-search').addEventListener('input',e=>renderCandidates(e.target.value))}
function renderCandidates(q){const list=catalog.filter(p=>[p.name,p.symbol,p.account||''].join(' ').toLowerCase().includes(q.toLowerCase().trim()));$('#candidates').innerHTML=list.length?list.map(p=>`<button class="candidate" data-add-project="${p.id}">${token(p)}<span><strong>${p.name} <span class="tag">${p.symbol}</span></strong><small>${p.account||'无统一官方账号'}</small></span><b>${state.projects.includes(p.id)?'已关注':'＋ 关注'}</b></button>`).join(''):'<div class="empty">未找到测试项目。</div>'}
const ruleTypes={news:'重要项目消息',price:'价格涨跌幅',oi:'OI 变化',ema:'上穿 EMA 200 / 360',level:'突破自定义价位',combo:'EMA 突破 + OI 增长'};
function ruleDescription(r){return r.type==='news'?'高重要性新消息与实质性后续进展':r.type==='ema'?`${r.period} · 从两线下方上穿 EMA 200 和 EMA 360`:r.type==='level'?`${r.period} · 上穿 $${r.threshold}`:r.type==='combo'?`${r.period} 上穿双均线，同时过去 1h 币本位 OI 增长 ≥ ${r.threshold}%`:`${r.period} · ${r.type==='oi'?'币本位 OI':'价格'}涨跌幅绝对值 ≥ ${r.threshold}%`}
function renderRules(){let rules=state.rules.filter(r=>!state.query||[r.name,catalog.find(p=>p.id===r.p)?.name].join(' ').toLowerCase().includes(state.query.toLowerCase()));$('#feed').innerHTML=`<div class="feed-toolbar"><span>${rules.length} 条提醒规则 · 仅保存配置</span><button class="primary" data-action="rule">＋ 新建规则</button></div>${rules.length?rules.map(r=>`<article class="rule-card"><div class="rule-head"><div><h3>${escapeHtml(r.name)}</h3><span class="tag">${catalog.find(p=>p.id===r.p)?.name||'项目'}</span> <span class="rule-status">${r.on?'配置已启用':'配置已暂停'} · 未运行</span></div><button class="switch" role="switch" aria-label="启用 ${escapeHtml(r.name)}" aria-checked="${r.on}" data-toggle-rule="${r.id}"></button></div><p>${escapeHtml(ruleDescription(r))}<br>${r.type==='news'?'新增实质进展':(['oi','price'].includes(r.type)?'达到阈值':(r.confirm==='close'?'收盘确认':'快速预警'))} · ${{instant:'即时通知',digest:'半小时摘要',site:'仅站内记录'}[r.notify]} · 未连接通知渠道</p><div class="rule-actions"><button data-edit-rule="${r.id}">编辑规则</button><button data-delete-rule="${r.id}">删除</button></div></article>`).join(''):'<div class="empty">暂无匹配的规则。</div>'}`}
function openRule(id){const rule=state.rules.find(r=>r.id===id)||{p:state.project||state.projects[0],name:'',type:'ema',period:'4h',threshold:5,confirm:'close',notify:'instant',on:true};showForm(`${formTitle(id?'编辑提醒规则':'新建提醒规则')}<p>配置保存在当前浏览器。自定义规则暂不运行；右侧展示固定 4h EMA 与 1h OI 实测。</p><form id="rule-form"><label class="field">规则名称<input name="name" required maxlength="60" value="${escapeHtml(rule.name)}" placeholder="例如：4 小时双均线突破"></label><div class="form-grid"><label class="field">项目<select name="p">${state.projects.map(id=>`<option value="${id}" ${rule.p===id?'selected':''}>${catalog.find(p=>p.id===id).name}</option>`).join('')}</select></label><label class="field">信号类型<select name="type">${Object.entries(ruleTypes).map(([k,v])=>`<option value="${k}" ${rule.type===k?'selected':''}>${v}</option>`).join('')}</select></label><label class="field" id="period-field">K 线周期 / 变化窗口<select name="period">${['15m','1h','4h','1d'].map(k=>`<option value="${k}" ${rule.period===k?'selected':''}>${k}</option>`).join('')}</select></label><label class="field" id="threshold-field"><span id="threshold-label">变化阈值（%）</span><input name="threshold" type="number" min="0.01" max="10000000" step="any" value="${rule.threshold}"></label><label class="field" id="confirm-field">确认方式<select name="confirm"><option value="close" ${rule.confirm==='close'?'selected':''}>收盘确认</option><option value="fast" ${rule.confirm==='fast'?'selected':''}>快速预警</option></select></label><label class="field">通知偏好<select name="notify">${Object.entries({instant:'即时通知',digest:'半小时摘要',site:'仅站内记录'}).map(([k,v])=>`<option value="${k}" ${rule.notify===k?'selected':''}>${v}</option>`).join('')}</select></label></div><div class="evidence" id="rule-explainer"></div><div class="modal-footer"><button type="button" class="secondary" data-close>取消</button><button type="submit" class="primary">保存规则</button></div></form>`);const form=$('#rule-form');function fields(){let type=form.elements.type.value;$('#threshold-field').hidden=['ema','news'].includes(type);form.elements.threshold.required=!['ema','news'].includes(type);$('#threshold-label').textContent=type==='level'?'关键价位（USD）':type==='combo'?'过去 1h OI 增幅（%）':'变化阈值（%）';$('#period-field').hidden=type==='news';$('#confirm-field').hidden=['news','oi','price'].includes(type);$('#rule-explainer').textContent=type==='news'?'来源、证据状态与重要性分别呈现；同一事件仅在新增实质信息时提醒。':type==='combo'?'Binance USDⓈ-M 永续（规则配置尚未启用） · EMA 按所选周期计算；OI 固定为过去 1 小时币本位变化。两个条件均满足才触发。':'Binance USDⓈ-M 永续（规则配置尚未启用） · '+(type==='ema'?'EMA 使用所选周期的 200 / 360 根 K 线；不足 360 根时不运行。':type==='oi'?'采用币本位 OI；涨跌幅取绝对值，不推断多空方向。':'同一突破不重复提醒，条件重置后才重新触发。')};fields();form.elements.type.addEventListener('change',fields);form.addEventListener('submit',e=>{e.preventDefault();const data=Object.fromEntries(new FormData(form));if(!data.name.trim())return;const result={...data,id:id||Date.now(),name:data.name.trim(),threshold:Number(data.threshold),on:rule.on};if(id)state.rules=state.rules.map(r=>r.id===id?result:r);else state.rules.push(result);persist();$('#form-dialog').close();state.view='rules';state.project=null;state.query='';$('#search').value='';render();toast('规则已保存 · 自定义规则暂不执行')})}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;const d=b.dataset;if(d.close!==undefined){b.closest('dialog').close();return}if(d.view){state.view=d.view;state.project=null;state.filter='all';state.query='';$('#search').value='';render()}if(d.project){state.project=d.project;state.view='feed';state.filter='all';state.important=false;$('#important').checked=false;state.query='';$('#search').value='';render()}if(d.filter){state.filter=d.filter;render()}if(d.event)openDetail(Number(d.event));if(d.save){const id=Number(d.save);state.saved=state.saved.includes(id)?state.saved.filter(x=>x!==id):[...state.saved,id];persist();render();if($('#detail-dialog').open){$('#detail-dialog').close();openDetail(id)}toast(state.saved.includes(id)?'已加入稍后阅读':'已取消收藏')}if(d.addProject){if(state.projects.includes(d.addProject)){toast('该项目已在关注列表');return}state.projects.push(d.addProject);persist();$('#form-dialog').close();state.project=d.addProject;state.view='feed';state.query='';state.filter='all';$('#search').value='';render();toast('已关注 · 已添加到阅读列表')}if(d.detailRule){$('#detail-dialog').close();state.project=d.detailRule;openRule()}if(d.editRule)openRule(Number(d.editRule));if(d.toggleRule){state.rules=state.rules.map(r=>r.id===Number(d.toggleRule)?{...r,on:!r.on}:r);persist();render()}if(d.deleteRule){const r=state.rules.find(x=>x.id===Number(d.deleteRule));showForm(`${formTitle('删除提醒规则')}<p>删除「${escapeHtml(r.name)}」？此操作只影响本设备的本地配置。</p><div class="modal-footer"><button class="secondary" data-close>取消</button><button class="primary" data-confirm-delete="${r.id}">删除规则</button></div>`)}if(d.confirmDelete){state.rules=state.rules.filter(r=>r.id!==Number(d.confirmDelete));persist();$('#form-dialog').close();render();toast('规则已删除')}if(d.action==='add')openAdd();if(d.action==='rule')openRule();if(d.action==='read-all'){state.read=[...new Set([...state.read,...filteredEvents().map(e=>e.id)])];persist();render();toast('当前列表已标记为已读')}if(d.action==='clear'){state.query='';state.filter='all';state.important=false;$('#search').value='';$('#important').checked=false;render()}if(d.action==='help')showForm(`${formTitle('关于这个 Demo')}<p>Signal 是项目新闻与市场信号的阅读器原型。你可以切换项目、筛选事件、收藏、查看详情，以及保存提醒规则。</p><div class="evidence">所有新闻、行情、时间和来源身份均为虚构示例。未连接 OpenNews、OpenTwitter 或交易所；没有后台监控和真实推送。偏好仅保存于当前浏览器。</div>`);if(d.action==='sources'){const p=catalog.find(p=>p.id===state.project);showForm(`${formTitle(p.name+' · 信息来源')}<p>来源结构演示，不代表已经完成账号发现或身份核验。</p><div class="source-row">官方入口候选<small>${p.account||'无统一官方账号'} · 待实时核验</small></div><div class="source-row">团队成员<small>尚未接入 · 需要官网或官方介绍佐证</small></div><div class="source-row">近期讨论者<small>尚未接入 · 搜索与原创内容筛选后加入</small></div><div class="source-row">行情数据<small>静态模拟数据 · 未连接交易所</small></div>`)}});
$('#search').addEventListener('input',e=>{state.query=e.target.value;render()});$('#important').addEventListener('change',e=>{state.important=e.target.checked;render()});document.addEventListener('keydown',e=>{if(e.key==='/'&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)&&!$('dialog[open]')){e.preventDefault();$('#search').focus()}});document.querySelectorAll('dialog').forEach(d=>d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close()}}));
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'filter_live_events',title:'筛选真实事件',description:'切换 Signal 真实事件分类，只改变当前阅读视图。',inputSchema:{type:'object',properties:{category:{type:'string',enum:['all','news','market','combo']}},required:['category'],additionalProperties:false},annotations:{readOnlyHint:false},execute(input){if(!input||!['all','news','market','combo'].includes(input.category))throw new Error('无效事件分类');state.view='feed';state.filter=input.category;render();return {category:state.filter,count:filteredEvents().length,demo:false}}})).catch(()=>{})}catch{}}
let liveData=null,liveError='';
function collectorSummary(){const c=liveData?.collectors||{};return '<h3>后台运行状态</h3>'+Object.entries(c).map(([key,v])=>`<div class="source-row">${({market:'行情采集',news:'新闻与团队推文',social:'近期讨论者'})[key]||escapeHtml(key)} · ${v.running?'采集中':'等待下次采集'}<small>最近完成：${formatTime(v.lastCompletedAt)}<br>下次计划：${formatTime(v.nextRunAt)}${v.lastError?'<br>最近异常：'+escapeHtml(v.lastError)+' · '+formatTime(v.lastErrorAt):''}</small></div>`).join('')}
function safeUrl(url){try{const u=new URL(url);return u.protocol==='https:'?u.href:'#'}catch{return '#'}}
function formatTime(ms){return ms?new Date(ms).toLocaleString('zh-CN',{hour12:false}):'未提供'}
function number(v){return Number.isFinite(v)?v.toLocaleString('en-US',{maximumFractionDigits:6}):'—'}
function pct(v){return Number.isFinite(v)?(v>0?'+':'')+v.toFixed(2)+'%':'—'}
function marketEvents(data){return catalog.flatMap((p,i)=>{const m=data.markets[p.id];if(!m)return [];let out=[];const stale=Date.now()-m.fetchedAt>180000;const common={p:p.id,type:'market',high:false,source:m.source,discoveredAt:m.fetchedAt,url:'https://www.binance.com/en/futures/'+p.symbol+'USDT',sources:stale?'数据已过期':'数据快照 · 非触发提醒',time:formatTime(m.priceAt||m.fetchedAt),topic:'行情快照'};out.push({...common,id:900001+i,title:p.symbol+' · '+(m.price?'$'+number(m.price):'行情暂不可用')+'，24h '+pct(m.change24h),summary:`4h EMA 200：${number(m.ema200)} · EMA 360：${number(m.ema360)}。${m.ema200?('最近收盘'+(m.above200&&m.above360?'位于两条均线上方':!m.above200&&!m.above360?'位于两条均线下方':'位于两条均线之间')):'均线数据不足或接口不可用'}。`,metrics:[['币本位 OI',number(m.oi)],['约 1h OI',pct(m.oiChange1h)],['4h 收盘',number(m.close4h)]],detail:`交易对 ${m.symbol}，来源 ${m.source}。价格更新时间 ${formatTime(m.priceAt)}；最近已收盘 4h K 线 ${formatTime(m.candleAt)}；OI 窗口 ${formatTime(m.oiFrom)} 至 ${formatTime(m.oiAt)}。EMA 以首 N 根收盘价均值为种子，随后递推；使用 ${m.klineCount||0} 根已收盘 K 线。${Object.keys(m.errors).length?'数据缺口：'+Object.entries(m.errors).map(([k,v])=>k+' '+v).join('；'):''}`,uncertain:'这是最新状态，不等于刚发生突破。OI 为 Binance 单交易所币本位数量，不能据此判断多空主导。'});
const alignedOi=Math.abs((m.oiAt||0)-(m.candleAt||0))<=3600000;
if(m.cross&&!stale){out.push({...common,id:Number(String(m.candleAt).slice(0,-3))+i,type:alignedOi&&Math.abs(m.oiChange1h||0)>=5?'combo':'market',high:true,topic:'均线穿越',sources:'最近已收盘 K 线',time:formatTime(m.candleAt),title:p.symbol+' · 4h 收盘'+(m.cross==='up'?'上穿双均线上沿':'下穿双均线下沿'),summary:'上一根与本根已收盘 K 线相对 EMA 区间的位置发生变化。'+(alignedOi&&Math.abs(m.oiChange1h||0)>=5?'在相近窗口内，最近约 1h OI 变化绝对值达到 5%。':''),uncertain:'穿越按相邻收盘价与各自时点均线判断；OI 窗口与收盘时点可能不重合。没有价格预测含义。'})}return out})}
const originalRender=render;
render=function(){originalRender();const selected=catalog.find(p=>p.id===state.project);$('.demo-status').textContent=liveError?'◌ 连接中断':'◌ 真实数据测试';$('.demo-banner').innerHTML=`<span>LIVE BETA</span> ${liveError?escapeHtml(liveError):'行情 60 秒更新 · 资讯 30 分钟检查 · '+providerHealth(liveData?.sources)} <button class="text-button" data-live-refresh>刷新视图</button>`;
$('.brief').innerHTML=`<div class="section-kicker">DATA COVERAGE <span>来源覆盖</span></div><h2>真实变化，<br>清楚标注。</h2><p>行情来自 Binance 永续。官网资讯保留原文和发布时间，旧文章不会伪装成刚发生的新闻。</p><div class="brief-stats"><div><strong>${liveData?Object.values(liveData.markets).filter(m=>m.price).length:0}/${catalog.length}</strong><span>行情已返回</span></div><div><strong>${events.filter(e=>e.type==='news').length}</strong><span>已采集资讯</span></div></div>`;
const rails=document.querySelectorAll('.rail-block');rails[0].querySelector('.rail-title').innerHTML='市场观察 <span>Binance 永续 · 24h</span>';
$('#market-watch').innerHTML=catalog.map(p=>{const m=liveData?.markets[p.id];return `<button class="watch-row" data-project="${p.id}" style="width:100%;text-align:left">${token(p)}<div class="name">${p.symbol}<small>${m?formatTime(m.priceAt).split(' ')[1]||'':''}</small></div><div class="price" style="margin-left:auto">${m?.price?'$'+number(m.price):'—'}<small class="${m?.change24h<0?'down':''}">${pct(m?.change24h)}</small></div></button>`}).join('');
rails[1].innerHTML='<div class="rail-title">采集状态 <span>非全网覆盖</span></div>'+catalog.filter(p=>!selected||p.id===selected.id).map(p=>{const statuses=liveData?.sources[p.id];return `<div class="source-row">${p.name}<small>${statuses?Object.entries(statuses).map(([n,s])=>escapeHtml(n+'：'+sourceHealth(s).label)+(s.lastSuccessAt?'<br>最近成功：'+formatTime(s.lastSuccessAt):'')).join('<br>'):'首次采集中…'}</small></div>`}).join('');$('.quiet-note').innerHTML='最近完成采集<br>'+formatTime(liveData?.updatedAt)+'<br><span>后台关闭后停止更新。</span>';
if(selected){const m=liveData?.markets[selected.id];$('#project-overview').innerHTML=`<section class="project-overview">${token(selected)}<div><h2>${selected.symbol} <span class="tag">${m?.price?'$'+number(m.price):'等待行情'}</span></h2><p>${selected.account} · Binance ${selected.symbol}USDT 永续</p></div><button class="secondary" data-action="sources">查看来源</button><button class="primary" data-action="rule">＋ 配置提醒</button></section>`}
if(!events.length&&state.view!=='rules')$('#feed').innerHTML='<div class="empty"><h3>正在连接真实数据</h3><p>首次获取 K 线与官方资讯可能需要几十秒。不可用来源会单独标注。</p></div>';
};
async function refreshLive(){try{const res=await fetch('/api/live',{cache:'no-store'});if(!res.ok)throw Error('后端返回 '+res.status);const data=await res.json();liveData=data;window.dispatchEvent(new CustomEvent('signal-live',{detail:data}));catalog.splice(0,catalog.length,...data.projects.map(p=>({...p,account:p.account?'@'+p.account:''})));state.projects=catalog.filter(p=>!state.hiddenProjects.includes(p.id)).map(p=>p.id).sort((a,b)=>{const ai=state.projectOrder.indexOf(a),bi=state.projectOrder.indexOf(b);return (ai<0?9999:ai)-(bi<0?9999:bi)});if(state.project&&!state.projects.includes(state.project))state.project=null;liveError='';const news=[...data.events.filter(e=>!e.providerKind&&!(data.intelligence?.events||[]).some(x=>x.id===e.id)),...(data.intelligence?.events||[])].map(e=>({...e,newsId:e.id,id:parseInt(e.id.slice(5,17),16),time:e.publishedAt?(e.datePrecision==='day'?new Date(e.publishedAt).toISOString().slice(0,10):formatTime(e.publishedAt)):'发布时间未知',sources:(e.sourceCount>1?e.sourceCount+' 个来源入口':'原文索引')+' · '+(e.freshness==='archive'?'历史内容':e.freshness==='unknown'?'时间未知':'未独立核实'),detail:e.summary}));events.splice(0,events.length,...[...news,...marketEvents(data).filter(e=>e.topic!=='行情快照')].sort((a,b)=>(b.publishedAt||(b.type==='news'?0:b.discoveredAt)||0)-(a.publishedAt||(a.type==='news'?0:a.discoveredAt)||0)));render()}catch(e){liveError='无法连接采集服务，现有内容可能过期。';render()}}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.hasAttribute('data-live-refresh')){refreshLive();toast('刷新已采集数据；后台按固定频率更新')}if(b.dataset.action==='sources'){e.stopImmediatePropagation();if(b.dataset.action==='help'){showForm(`${formTitle('真实数据测试')}<p>测试项目：SOON SVM、NEAR Protocol、Phala、Nillion。行情每分钟采集，新闻每半小时检查。</p><div class="evidence">官方文章保留原始日期。Token 未配置时不采集 X 或 OpenNews。团队账号保留身份依据，近期讨论账号通过实际推文检索；KOL 身份未单独核实。自定义规则已由本地服务执行，触发结果保存为站内记录；外部推送尚未接入。</div>${collectorSummary()}`);return}const p=catalog.find(x=>x.id===state.project);const statuses=liveData?.sources[p.id]||{};showForm(`${formTitle(p.name+' · 来源覆盖')}<div class="source-row"><a class="source-link" target="_blank" rel="noopener noreferrer" href="https://x.com/${p.account.slice(1)}">${p.account} ↗</a><small>项目账号；团队与近期讨论者见项目页</small></div>${Object.entries(statuses).map(([name,s])=>`<div class="source-row">${escapeHtml(name)}<small>${escapeHtml(s.message||s.status)}${s.lastSuccessAt?'<br>最近成功：'+formatTime(s.lastSuccessAt):''}</small></div>`).join('')}<div class="source-row">Binance ${p.symbol}USDT<small>永续价格、币本位 OI、4h EMA 200 / 360</small></div>`)}},true);
render();refreshLive();setInterval(refreshLive,15000);
// Source and age filters apply to news; market observations keep their own timestamps.
let newsWindow='7',newsSource='all';
const originalFilteredEvents=filteredEvents;
filteredEvents=function(){return originalFilteredEvents().filter(e=>{if(e.type!=='news')return newsSource==='all';if(newsSource!=='all'&&e.channel!==newsSource&&!e.sourcesList?.some(s=>s.channel===newsSource))return false;if(newsWindow==='all')return true;return e.publishedAt&&e.publishedAt<=Date.now()+300000&&e.publishedAt>=Date.now()-Number(newsWindow)*86400000})};
const newsFilters=document.createElement('div');newsFilters.className='news-filters';newsFilters.innerHTML='<label>时间 <select id="news-window"><option value="7">近 7 天</option><option value="1">近 24 小时</option><option value="30">近 30 天</option><option value="all">全部 / 历史</option></select></label><label>来源 <select id="news-source"><option value="all">全部来源</option><option value="opennews">OpenNews</option><option value="x">官方 X</option><option value="team">团队 X</option><option value="official">项目官网</option></select></label>';
$('#feed-controls').append(newsFilters);$('#news-window').addEventListener('change',e=>{newsWindow=e.target.value;render()});$('#news-source').addEventListener('change',e=>{newsSource=e.target.value;render()});
const qualityDetail=openDetail;
openDetail=function(id){qualityDetail(id);const e=events.find(e=>e.id===id);if(!e||e.type!=='news')return;const section=document.createElement('section');section.className='quality-evidence';section.innerHTML=`<h3>为什么出现在这里</h3><div class="evidence">${escapeHtml(e.matchReason||'已配置的项目官方来源')}<br>${escapeHtml(e.priorityReason||'未进行自动重要性判断')}<br>证据类型：${escapeHtml(e.evidence||'来源表述')}<br>${escapeHtml(e.independenceNote||'来源表述未经独立核实')}</div>${e.providerRating?.score!=null?`<p>OpenNews 提供方评分：${escapeHtml(e.providerRating.score)} / 100（参考值，非本站核实结论）</p>`:''}<h3>原始来源</h3>${(e.sourcesList||[{name:e.source,url:e.url}]).map(s=>`<div class="source-row"><a class="source-link" target="_blank" rel="noopener noreferrer" href="${escapeHtml(safeUrl(s.url))}">${escapeHtml(s.name)} ↗</a></div>`).join('')}`;$('#detail-content .modal-footer').before(section)};
render();

document.addEventListener("click",e=>{if(e.target.closest('[data-action="clear"]')){newsWindow="7";newsSource="all";$("#news-window").value="7";$("#news-source").value="all";}},true);

